Nat4	loadPersistents_HIToolbar(V_Environment environment);
Nat4	loadPersistents_HIToolbar(V_Environment environment)
{
	V_Value tempPersistent = NULL;
	V_Dictionary dictionary = environment->persistentsTable;

	tempPersistent = create_persistentNode("HIToolbar/HIObject Class",tempPersistent_HIToolbar_2F_HIObject_20_Class,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIToolbar Item Object/HIObject Class",tempPersistent_HIToolbar_20_Item_20_Object_2F_HIObject_20_Class,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	return kNOERROR;

}

